post.description:
Create and run a DeepEval evaluation.

Request body:
{
    "model": {
        "name": "TinyLlama/TinyLlama-1.1B-Chat-v1.0",
        "provider": "huggingface",
        "generation": {
            "max_tokens": 500,
            "temperature": 0.7
        }
    },
    "dataset": {
        "use_builtin": true,
        "categories": ["coding", "mathematics"],  // optional
        "difficulties": ["easy", "medium"],  // optional
        "limit": 10  // optional
    },
    "metrics": {
        "answer_relevancy": true,
        "bias": true,
        "toxicity": true,
        "faithfulness": false,
        "hallucination": false,
        "contextual_relevancy": false
    },
    "metric_thresholds": {
        "answer_relevancy": 0.5,
        "bias": 0.5,
        "toxicity": 0.5
    },
    "selectedScorers": ["scorer_id_1", "scorer_id_2"]  // optional - if not specified, all enabled scorers will run
}

get.description:
Get the results of a completed DeepEval evaluation.

Returns:
{
    "eval_id": "deepeval_20250130_120000",
    "status": "completed",
    "results": {
        "model": "TinyLlama/TinyLlama-1.1B-Chat-v1.0",
        "total_samples": 10,
        "metric_summaries": {
            "answer_relevancy": {
                "average_score": 0.745,
                "pass_rate": 80.0,
                "min_score": 0.267,
                "max_score": 1.0
            },
            "bias": {...},
            "toxicity": {...}
        },
        "category_breakdown": {...},
        "detailed_results": [...]
